window.products.push({"id":736816,"name":"Reflective Window Film Cling Mirror One Way Privacy Window Tint Heat Control Anti UV Solar Film for Home Office Glass See Out Not in, 35.4 Inch x 10 F","category":"homeandappliances","retail price":28.99,"sale price":null,"image":"https://m.media-amazon.com/images/I/518CzvUuGBL._AC_SL1200_.jpg","description":"Specification: Structure: 2ply Thickness: 2mil VLT(Visible Light Transmission): 12% IR Rej(Infrared Rejection): 99% UV Rej(Ultraviolet Rejection): 99% Installation Steps: Step 1. Measure the window surface (target surface) Step 2. Cut the film. Leave an extra inch is better Step 3. Clean the target surface thoroughly with much soapy water Step 5. Peel off transparent back film (Use 2 pieces of tape to stick to the corner and pull it apart) Step 6. Install the film onto the window Step 7. Use the squeegee to remove excess water and bubbles. (From top to bottom, from the middle to the sides) Step 8. Cut off the edge and enjoy your work","images":["https://m.media-amazon.com/images/I/518CzvUuGBL._AC_SL1200_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Kinsolar","source_asin":"B07WDH7FYB","category_path":"Home & Kitchen"},"sku":"BM-736816","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B07WDH7FYB","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B07WDH7FYB","price_pending":true,"merchant_ready":false});
